const KEY='opos-v0';
const seed={page:'dashboard',running:true,paused:false,bottles:42,target:72,speed:1,toast:'',menu:false,inventory:{Water:78,Mango:53,Lemon:61,Sweetener:73,'Strawberry Lemonade':40,'Classic Lemonade':65,'Half & Half':65,'Blueberry Lemonade':58,'Raspberry Lemonade':58,'Pineapple Lemonade':62,'Alkaline Water':78},queue:[{id:1,flavor:'Mango',qty:72,status:'RUNNING',time:'10:30 AM'},{id:2,flavor:'Strawberry Lemonade',qty:72,status:'NEXT',time:'12:00 PM'},{id:3,flavor:'Classic Lemonade',qty:48,status:'QUEUED',time:'1:30 PM'},{id:4,flavor:'Half & Half',qty:48,status:'QUEUED',time:'2:45 PM'}],batches:[{id:'MS-261007-M01',flavor:'Mango',qty:72,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-S01',flavor:'Strawberry Lemonade',qty:48,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-C01',flavor:'Classic Lemonade',qty:24,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-H01',flavor:'Half & Half',qty:24,date:'Oct 07, 2026',status:'COMPLETED'}]};
let s=JSON.parse(localStorage.getItem(KEY)||'null')||seed; if(s.inventory){if(!('Strawberry' in s.inventory))s.inventory.Strawberry=40;for(const [name,value] of Object.entries({'Classic Lemonade':65,'Half & Half':65,'Blueberry Lemonade':58,'Raspberry Lemonade':58,'Pineapple Lemonade':62,'Alkaline Water':78}))if(!(name in s.inventory))s.inventory[name]=value;} if(s.queue){s.queue=s.queue.map(q=>({...q,flavor:q.flavor==='Kiwi'?'Classic Lemonade':q.flavor==='Pink Lemonade'?'Half & Half':q.flavor}));} if(!s.activeRun){let current=s.queue?.find(q=>q.status==='RUNNING');s.activeRun=current||{id:'run-1',flavor:'Mango',qty:72,status:s.paused?'PAUSED':s.running?'RUNNING':'READY'};} if(!s.recipes){s.recipes={};} if(s.running&&s.activeRun&&!s.queue.some(q=>String(q.id)===String(s.activeRun.id)))s.queue.unshift(s.activeRun); let timer;
const flavors={Mango:['55%','25%','15%','5%'], 'Strawberry Lemonade':['60%','25%','10%','5%'],'Classic Lemonade':['60%','20%','15%','5%'],'Half & Half':['55%','25%','15%','5%'],'Blueberry Lemonade':['55%','25%','15%','5%'],'Raspberry Lemonade':['55%','25%','15%','5%'],'Pineapple Lemonade':['55%','25%','15%','5%'],'Alkaline Water':['70%','0%','20%','10%']};
const catalog=[['Mango','mango-lemonade-cutout.webp','#f29a17'],['Strawberry Lemonade','strawberry-lemonade-cutout.webp','#e74345'],['Classic Lemonade','classic-lemonade-cutout.webp','#f5c62d'],['Half & Half','half-half-cutout.webp','#c88d34'],['Blueberry Lemonade','blueberry-lemonade-cutout.webp','#6277dd'],['Raspberry Lemonade','raspberry-lemonade-cutout.webp','#c23f64'],['Pineapple Lemonade','pineapple-lemonade-cutout.webp','#e9ba24'],['Alkaline Water','alkaline-water-cutout.webp','#59aee0']];
const nav=[['dashboard','Dashboard','▦'],['queue','Queue','☷'],['prep','Prep','◒'],['recipes','Recipes','◈'],['relay','Recipe Relay','◉'],['inventory','Inventory','▥'],['ingredients','Ingredients','∑'],['production','Production','▶'],['cleaning','Cleaning','♻'],['batches','Batches','▤'],['reports','Reports','◒'],['settings','Settings','⚙']];
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const [name,value] of Object.entries({Water:78,Lemon:61,Sweetener:73,...Object.fromEntries(catalog.map(([f])=>[f,55]))}))if(!(name in s.inventory))s.inventory[name]=value;
if('Green Tea' in s.inventory)delete s.inventory['Green Tea'];
if(s.inventory.Strawberry){s.inventory['Strawberry Lemonade']??=s.inventory.Strawberry;delete s.inventory.Strawberry}
s.queue=(s.queue||[]).map(q=>({...q,flavor:q.flavor==='Kiwi'?'Classic Lemonade':q.flavor==='Pink Lemonade'?'Half & Half':q.flavor==='Strawberry'?'Strawberry Lemonade':q.flavor}));s.batches=(s.batches||[]).map(b=>({...b,flavor:b.flavor==='Strawberry'?'Strawberry Lemonade':b.flavor})).filter(b=>catalog.some(([f])=>f===b.flavor));
s.recipes=s.recipes||{};for(const [f] of catalog){let old=s.recipes[f];if(Array.isArray(old)&&old.length===5){old=[`${(parseFloat(old[0])||0)+(parseFloat(old[1])||0)}%`,old[2],old[3],old[4]];s.recipes[f]=old}if(Array.isArray(s.recipes[f])&&s.recipes[f].join('|')===flavors[f].join('|'))delete s.recipes[f]}
s.costs=s.costs||{Water:.18,Lemon:.92,Sweetener:.48};delete s.costs['Green Tea'];delete s.inventory['Green Tea'];s.ouncesPerBottle=Number(s.ouncesPerBottle)||16;s.builderQty=s.builderQty??48;s.builderFlavor=s.builderFlavor||'Mango';if(!s.dailySeeded&&!s.batches.length){s.batches=[{id:'MS-261007-M01',flavor:'Mango',qty:72,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-S01',flavor:'Strawberry Lemonade',qty:48,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-C01',flavor:'Classic Lemonade',qty:24,date:'Oct 07, 2026',status:'COMPLETED'},{id:'MS-261007-H01',flavor:'Half & Half',qty:24,date:'Oct 07, 2026',status:'COMPLETED'}]}s.dailySeeded=true;
function save(){localStorage.setItem(KEY,JSON.stringify(s))} function item(flavor){return catalog.find(x=>x[0]===flavor)||catalog[0]} function flavorColor(name){return item(name)[2]} function channelNames(flavor){return ['Water',flavor,'Lemon','Sweetener']} function pct(){return Math.min(100,Math.round(s.bottles/Math.max(1,s.target)*100))} function flash(t){s.toast=t;save();render();setTimeout(()=>{s.toast='';render()},2400)} function recipeFor(flavor){return (s.recipes||{})[flavor]||flavors[flavor]||flavors.Mango} function runId(flavor){return `MS-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${flavor.split(/\s+/).map(x=>x[0]).join('').toUpperCase()}${String(Date.now()).slice(-2)}`}
function tank(name){let v=s.inventory[name],color=name==='Water'?'#5db9e9':name==='Lemon'?'#f5c62d':name==='Sweetener'?'#e7e1c9':flavorColor(name);return `<div class="tank-card" style="--tank-color:${color}"><div class="tank"><i style="height:${v}%"></i><b>${Number(v).toFixed(0)}%</b></div><div><strong>${name.toUpperCase()}</strong><small>${(v*3/100).toFixed(1)} / 3 GAL</small><span class="${v<55?'warn':'good'}">${v<55?'LOW':'READY'}</span></div></div>`}
function header(){return `${s.menu?'<button class="nav-scrim" data-action="close-menu" aria-label="Close navigation"></button>':''}<header><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><img src="/assets/monsta-squeeze-logo.png" alt="Monsta Squeeze"><div class="brand"><b>PRODUCTION</b><strong>OS</strong><small>OPERATIONS OS</small></div><nav class="${s.menu?'mobile-open':''}">${nav.map(n=>`<button class="${s.page===n[0]?'active':''}" data-page="${n[0]}"><i>${n[2]}</i>${n[1]}</button>`).join('')}</nav><div class="sys"><span class="dot"></span> SYSTEM RUNNING <b data-action="settings">⚙</b></div></header>`}
function mobileNav(){return `<nav class="mobile-bottom" aria-label="Mobile navigation"><button data-page="dashboard" class="${s.page==='dashboard'?'active':''}"><i>⌂</i>Home</button><button data-page="queue" class="${s.page==='queue'?'active':''}"><i>☷</i>Queue</button><button data-page="recipes" class="${s.page==='recipes'?'active':''}"><i>◈</i>Recipes</button><button data-page="inventory" class="${s.page==='inventory'?'active':''}"><i>▥</i>Inventory</button><button data-action="menu"><i>•••</i>More</button></nav>`}
function runCard(){let run=s.activeRun||{flavor:'Mango',qty:72,status:'READY'},product=item(run.flavor),stages=s.bottles===0?0:Math.min(4,Math.ceil(pct()/25));return `<section class="hero-card run-live ${s.running&&!s.paused?'is-running':''}"><div class="run-art"><img src="/assets/${product[1]}" alt="${esc(run.flavor)} bottle"></div><div class="run-copy"><label class="${s.flowAlert?'flow-error-label':''}">● ${s.flowAlert?'FLOW ERROR':s.paused?'PAUSED':s.running?'NOW RUNNING':run.status||'READY'}</label><h1>${esc(run.flavor)}</h1><p>Batch ${esc(s.batchId||runId(run.flavor))}</p><div class="count"><b>${s.bottles}</b> / ${s.target} <small>${pct()}%</small></div><div class="bar"><i style="width:${pct()}%"></i></div><div class="meta"><span>Est. ${Math.max(0,Math.ceil((s.target-s.bottles)/4))} min remaining</span><span>Flow rate: ${Number.isFinite(s.flowRate)?s.flowRate.toFixed(1):'2.1'} L/min</span><span>Bottle size: ${s.bottleSize||'16 oz'}</span></div><div class="run-stages">${['MIX','FILL','CAP','LABEL'].map((x,i)=>`<i class="${i<stages?'stage-active':''}">${x}</i>`).join('')}</div></div><div class="run-controls"><button data-action="${s.running&&!s.paused?'pause':'resume'}">${s.running&&!s.paused?'Ⅱ PAUSE':'▶ RESUME'}</button><button class="danger" data-action="stop">■ STOP</button><button class="yellow" data-action="complete">✓ COMPLETE</button></div></section>`}
function dashboardLegacy(){let planned=s.queue.reduce((sum,q)=>sum+Number(q.qty||0),0),today=new Date();return `<div class="page-head"><div><p class="eyebrow">OPERATIONS OS / OVERVIEW</p><h2>Production command center</h2></div><div class="date">${today.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'2-digit',year:'numeric'}).toUpperCase()}<br><b>${today.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</b></div></div>${runCard()}<div class="section-title"><h3>Ingredient reservoirs</h3><span class="sim">DEMO / SIMULATION</span></div><div class="tanks">${Object.keys(s.inventory).map(tank).join('')}</div><div class="dashboard-grid"><panel><div class="panel-head"><h3>Production queue</h3><button class="yellow" data-page="queue">+ ADD RUN</button></div>${s.queue.map((q,i)=>`<div class="queue-row"><b>0${i+1}</b><span class="flavor-dot d${i}"></span><strong>${q.flavor}</strong><span>${q.qty}</span><em class="status ${q.status.toLowerCase()}">${q.status}</em><small>${q.time}</small></div>`).join('')}</panel><panel><div class="panel-head"><h3>Today's production</h3><span class="muted">${planned} planned</span></div><div class="donut" style="--p:${Math.min(100,Math.round(s.bottles/Math.max(1,planned)*100))*3.6}deg"><b>${s.bottles}<small>/ ${planned}<br>bottles</small></b></div><div class="legend">${s.queue.map(q=>`<span><i></i>${q.flavor}<b>${q.qty}</b></span>`).join('')}</div></panel><panel><div class="panel-head"><h3>Quick actions</h3></div><div class="quick">${[['pause','Ⅱ','Pause'],['stop','■','Stop'],['prep','♨','Prep mode'],['relay','◉','Recipe relay'],['inventory','↗','Refill'],['cleaning','♻','Cleaning']].map(x=>`<button data-action="${x[0]}" data-page="${x[0]}"><i>${x[1]}</i>${x[2]}</button>`).join('')}</div></panel></div>`}
function prepLegacy(){let needs={};for(const q of s.queue){if(q.status==='COMPLETED')continue;let gallons=Number(q.qty||0)*(Number(s.ouncesPerBottle)||16)/128;channelNames(q.flavor).forEach((name,i)=>needs[name]=(needs[name]||0)+gallons*(parseFloat(recipeFor(q.flavor)[i])||0)/100)}let rows=Object.entries(needs).filter(([,need])=>need>0).map(([name,need])=>{let have=(Number(s.inventory[name])||0)*3/100;return{name,need,have,short:Math.max(0,need-have)}}),shortages=rows.filter(x=>x.short>.001);return `<div class="page-head"><div><p class="eyebrow">PLAN / PREP</p><h2>Today's prep requirements</h2></div><div class="readiness ${shortages.length?'blocked':'ready'}">● ${shortages.length?'PRODUCTION BLOCKED':'PRODUCTION READY'}</div></div><panel class="wide"><div class="panel-head"><h3>Ingredients</h3><span class="muted">Calculated live from ${s.queue.filter(q=>q.status!=='COMPLETED').reduce((a,q)=>a+Number(q.qty||0),0)} queued bottles · recipe ratios · ${s.ouncesPerBottle||16} oz bottles</span></div><table><thead><tr><th>INGREDIENT</th><th>NEED</th><th>HAVE</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(({name,need,have,short})=>`<tr><td><span class="flavor-dot" style="--flavor-color:${name==='Water'?'#5db9e9':name==='Lemon'?'#f5c62d':name==='Sweetener'?'#e7e1c9':flavorColor(name)}"></span>${esc(name)}</td><td>${need.toFixed(2)} gal</td><td>${have.toFixed(2)} gal</td><td><span class="status ${short?'blocked':'ready'}">${short?'LOW':'READY'}</span></td><td>${short?`<button class="tiny yellow" data-action="refill-one" data-flavor="${esc(name)}">REFILL</button>`:''}</td></tr>`).join('')}</tbody></table></panel>${shortages.length?`<panel class="shortage"><b>${shortages.length} INGREDIENT SHORTAGE${shortages.length>1?'S':''}</b><span>${shortages.map(x=>`${esc(x.name)} +${x.short.toFixed(2)} GAL`).join(' · ')}</span><button class="yellow" data-action="prep-refill">REFILL TO REQUIREMENT</button></panel>`:`<panel class="shortage prep-success"><b>ALL QUEUED RUNS PREPPED</b><span>Ingredient levels cover the current production plan.</span></panel>`}`}
function prep(){let needs={};for(const q of s.queue){if(q.status==='COMPLETED')continue;let g=Number(q.qty||0)*(Number(s.ouncesPerBottle)||16)/128;channelNames(q.flavor).forEach((n,i)=>needs[n]=(needs[n]||0)+g*(parseFloat(recipeFor(q.flavor)[i])||0)/100)}let rows=Object.entries(needs).filter(([,n])=>n>0).map(([name,need])=>{let level=Number(s.inventory[name])||0,have=level>=100?need:level*3/100;return{name,need,have,short:Math.max(0,need-have)}}),short=rows.filter(x=>x.short>.001);return `<div class="page-head"><div><p class="eyebrow">PLAN / PREP</p><h2>Today's prep requirements</h2></div><div class="readiness ${short.length?'blocked':'ready'}">● ${short.length?'PRODUCTION BLOCKED':'PRODUCTION READY'}</div></div><panel class="wide"><div class="panel-head"><h3>Ingredients</h3><span class="muted">Live from queued recipes · ${s.ouncesPerBottle} oz bottle basis</span></div><table><thead><tr><th>INGREDIENT</th><th>NEED</th><th>HAVE</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="flavor-dot" style="--flavor-color:${x.name==='Water'?'#5db9e9':x.name==='Lemon'?'#f5c62d':x.name==='Sweetener'?'#e7e1c9':flavorColor(x.name)}"></span>${esc(x.name)}</td><td>${x.need.toFixed(2)} gal</td><td>${x.have.toFixed(2)} gal</td><td><span class="status ${x.short?'blocked':'ready'}">${x.short?'LOW':'READY'}</span></td><td>${x.short?`<button class="tiny yellow" data-action="refill-one" data-flavor="${esc(x.name)}">REFILL</button>`:''}</td></tr>`).join('')}</tbody></table></panel>${short.length?`<panel class="shortage"><b>${short.length} INGREDIENT SHORTAGE${short.length>1?'S':''}</b><span>${short.map(x=>`${esc(x.name)} +${x.short.toFixed(2)} GAL`).join(' · ')}</span><button class="yellow" data-action="prep-refill">REFILL TO REQUIREMENT</button></panel>`:`<panel class="shortage prep-success"><b>PRODUCTION READY</b><span>Ingredient stock is staged for every queued run.</span></panel>`}`}
function dashboard(){let planned=s.queue.filter(q=>q.status!=='COMPLETED').reduce((sum,q)=>sum+Number(q.qty||0),0),today=new Date();return `<div class="page-head"><div><p class="eyebrow">OPERATIONS OS / OVERVIEW</p><h2>Production command center</h2></div><div class="date">${today.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'2-digit',year:'numeric'}).toUpperCase()}<br><b>${today.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</b></div></div>${runCard()}<div class="section-title"><h3>Ingredient reservoirs</h3><span class="sim">DEMO / SIMULATION</span></div><div class="tanks">${Object.keys(s.inventory).map(tank).join('')}</div><div class="dashboard-grid"><panel><div class="panel-head"><h3>Production queue</h3><button class="yellow" data-page="queue">+ ADD RUN</button></div>${s.queue.map((q,i)=>`<div class="queue-row" style="--flavor-color:${flavorColor(q.flavor)}"><b>0${i+1}</b><span class="flavor-dot"></span><strong>${esc(q.flavor)}</strong><span>${q.qty}</span><em class="status ${q.status.toLowerCase()}">${q.status}</em><small>${q.time||''}</small></div>`).join('')}</panel><panel><div class="panel-head"><h3>Today's production</h3><span class="muted">${planned} planned</span></div><div class="donut" style="--p:${Math.min(100,Math.round(s.bottles/Math.max(1,planned)*100))*3.6}deg"><b>${s.bottles}<small>/ ${planned}<br>bottles</small></b></div><div class="legend">${s.queue.filter(q=>q.status!=='COMPLETED').map(q=>`<span style="--flavor-color:${flavorColor(q.flavor)}"><i></i>${esc(q.flavor)}<b>${q.qty}</b></span>`).join('')}</div></panel><panel><div class="panel-head"><h3>Quick actions</h3></div><div class="quick">${[['pause','Ⅱ','Pause'],['stop','■','Stop'],['prep','♨','Prep mode'],['relay','◉','Recipe relay'],['inventory','↗','Refill'],['cleaning','♻','Cleaning']].map(x=>`<button data-action="${x[0]}" data-page="${x[0]}"><i>${x[1]}</i>${x[2]}</button>`).join('')}</div></panel></div>`}
function queue(){return `<div class="page-head"><div><p class="eyebrow">PLAN / QUEUE</p><h2>Production queue</h2></div><button class="yellow" data-action="add">＋ ADD RUN</button></div><panel class="wide"><div class="panel-head"><h3>Production plan</h3><b>${s.queue.filter(q=>q.status!=='COMPLETED').reduce((a,q)=>a+Number(q.qty||0),0)} BOTTLES</b></div><div class="queue-table">${s.queue.map((q,i)=>`<div class="queue-card" style="--flavor-color:${flavorColor(q.flavor)}"><span class="move-controls"><button class="icon move" data-action="move-up" data-id="${q.id}" aria-label="Move ${esc(q.flavor)} up" ${i===0?'disabled':''}>↑</button><button class="icon move" data-action="move-down" data-id="${q.id}" aria-label="Move ${esc(q.flavor)} down" ${i===s.queue.length-1?'disabled':''}>↓</button></span><b>0${i+1}</b><div class="bottle-thumb"><img src="/assets/${item(q.flavor)[1]}" alt=""></div><strong>${esc(q.flavor)}</strong><span>${q.qty} bottles<br><small>${s.bottleSize||'16 oz'} · ${Math.ceil(q.qty/4)} min est.</small></span><em class="status ${q.status.toLowerCase()}">${q.status}</em><button data-action="${s.activeRun?.id===q.id&&s.running?'production':'start'}" data-id="${q.id}">${s.activeRun?.id===q.id&&s.running?'OPEN':'START'}</button><button class="icon" data-action="delete" data-id="${q.id}">×</button></div>`).join('')}</div></panel><panel class="run-builder"><div class="panel-head"><h3>Build a run</h3><span class="sim">QUEUE → RUN → RELAY</span></div><div class="builder-fields"><label>Bottle quantity<input type="number" min="1" max="300" value="${s.builderQty??48}" data-run-qty></label><button class="yellow" data-action="create-run">ADD RUN TO QUEUE</button></div><div class="catalog-search">${catalog.map(([name,img,color])=>`<button class="${s.builderFlavor===name?'selected':''}" style="--flavor-color:${color}" data-action="choose-flavor" data-flavor="${esc(name)}"><img src="/assets/${img}" alt=""><span>${esc(name)}</span></button>`).join('')}</div></panel>`}
function recipes(){return `<div class="page-head"><div><p class="eyebrow">CONTROL / RECIPES</p><h2>Recipe library</h2></div><label class="recipe-search">⌕ <input data-recipe-search placeholder="Search Monsta flavors"></label></div><div class="recipe-grid">${catalog.map(([f,img,color],i)=>`<panel class="recipe" style="--flavor-color:${color}" data-recipe-card="${f.toLowerCase()}"><img src="/assets/${img}" alt="${f} bottle"><div><span class="eyebrow">MS-${String(10+i).padStart(3,'0')} · V${s.recipes[f]?'CUSTOM':'1.0'}</span><h3>${f}</h3><p>${recipeFor(f).join(' · ')}</p><span class="status ready">${s.recipes[f]?'CUSTOM':'ACTIVE'}</span></div><div class="recipe-actions"><button data-action="edit-recipe" data-flavor="${esc(f)}">EDIT</button><button data-action="load" data-flavor="${esc(f)}">LOAD TO RELAY</button><button class="yellow" data-action="run-recipe" data-flavor="${esc(f)}">NEW RUN</button></div></panel>`).join('')}</div>`}
function inventory(){return `<div class="page-head"><div><p class="eyebrow">MATERIALS / INVENTORY</p><h2>Inventory levels</h2></div><button class="yellow" data-action="refill">↗ REFILL ALL</button></div><div class="tanks inventory-tanks">${Object.keys(s.inventory).map(tank).join('')}</div><panel class="wide"><div class="panel-head"><h3>Supplies</h3><span class="muted">Last count 08:42 AM</span></div><table><tbody>${[['Bottles',240,310],['Caps',240,300],['Labels',240,275]].map(r=>`<tr><td>${r[0]}</td><td>${r[1]} needed</td><td>${r[2]} available</td><td><span class="status ready">READY</span></td></tr>`).join('')}</tbody></table></panel>`}
function recipeEditor(){let flavor=s.selectedRecipe||'Mango';if(s.draftFlavor!==flavor){s.draftFlavor=flavor;s.draftRecipe=recipeFor(flavor).map(x=>parseFloat(x)||0)}let values=s.draftRecipe,total=values.reduce((a,v)=>a+(Number(v)||0),0),valid=Math.abs(total-100)<.001;return `<div class="page-head"><div><p class="eyebrow">CONTROL / RECIPE EDITOR</p><h2>${esc(flavor)} recipe</h2></div><span class="readiness ${valid?'ready':'blocked'}">● ${valid?'RECIPE READY':'RECIPE INVALID'}</span></div><panel class="wide recipe-editor"><div class="panel-head"><h3>Ingredient ratios</h3><span class="sim">LOCAL SIMULATION RECIPE</span></div>${recipeControls(flavor,values)}<div class="recipe-editor-actions"><button data-page="recipes">CANCEL</button><button class="yellow" data-action="save-recipe" ${valid?'':'disabled'}>SAVE RECIPE</button><button data-action="load" data-flavor="${esc(flavor)}" ${valid?'':'disabled'}>LOAD TO RELAY</button></div></panel>`}
function recipeControls(flavor,values){let names=channelNames(flavor);return `<div class="recipe-controls">${names.map((name,i)=>`<label class="recipe-control" style="--flavor-color:${name==='Water'?'#5db9e9':name==='Lemon'?'#f5c62d':name==='Sweetener'?'#e7e1c9':flavorColor(flavor)}"><span>${esc(name.toUpperCase())}</span><div class="dial"><b>◉</b></div><div class="ratio-adjust"><button data-action="ratio-down" data-index="${i}">−</button><input type="number" min="0" max="100" step="1" value="${Number(values[i])||0}" data-ratio="${i}"><span>%</span><button data-action="ratio-up" data-index="${i}">＋</button></div></label>`).join('')}</div><div class="ratio-total ${Math.abs(values.reduce((a,v)=>a+Number(v||0),0)-100)<.001?'ready':'blocked'}">TOTAL <b data-recipe-total>${values.reduce((a,v)=>a+Number(v||0),0).toFixed(0)}%</b></div>`}
function production(){let flavor=s.activeRun?.flavor||'Mango',targets=recipeFor(flavor),labels=channelNames(flavor);return `<div class="page-head"><div><p class="eyebrow">PRODUCE / LIVE RUN</p><h2>Production run</h2></div><span class="sim">● SIMULATION ACTIVE</span></div>${runCard()}<panel class="wide"><div class="panel-head"><h3>Recipe performance</h3><span class="muted">Actual values fluctuate in demo mode</span></div><table><thead><tr><th>INGREDIENT</th><th>TARGET</th><th>ACTUAL</th><th>VARIANCE</th></tr></thead><tbody>${labels.map((x,i)=>{let target=Number.parseFloat(targets[i])||0,actual=Math.max(0,target+[-.1,.1,0,.05][i]);return `<tr><td>${esc(x)}</td><td>${target.toFixed(1)}%</td><td>${actual.toFixed(1)}%</td><td><span class="good">NORMAL</span></td></tr>`}).join('')}</tbody></table></panel>`}
function relay(){let flavor=s.selectedRecipe||s.activeRun?.flavor||'Mango';if(s.draftFlavor!==flavor){s.draftFlavor=flavor;s.draftRecipe=recipeFor(flavor).map(x=>parseFloat(x)||0)}let values=s.draftRecipe;return `<div class="page-head"><div><p class="eyebrow">CONTROL / MIXING</p><h2>Monsta Squeeze Recipe Relay</h2></div><span class="connected">● CONNECTED <small>SIMULATED</small></span></div><panel class="relay-panel"><div class="relay-top"><span>SELECTED RECIPE</span><select data-relay-flavor>${catalog.map(([f])=>`<option value="${esc(f)}" ${f===flavor?'selected':''}>${esc(f)}</option>`).join('')}</select><b>${esc(flavor.toUpperCase())} · ${s.recipes[flavor]?'CUSTOM':'V1'}</b><span class="status ready">CONNECTED</span></div>${recipeControls(flavor,values)}<div class="relay-actions"><button data-action="prime">PRIME</button><button class="yellow" data-action="load" data-flavor="${esc(flavor)}">LOAD RECIPE</button><button data-action="save-recipe" class="green" ${Math.abs(values.reduce((a,v)=>a+Number(v||0),0)-100)<.001?'':'disabled'}>SAVE RECIPE</button><button class="green" data-action="start">START CURRENT RUN</button><button class="danger" data-action="stop">STOP</button><button data-action="visual">VIEW FLOW</button></div><p class="muted">Recipe settings and flow are simulated. Changes can be saved locally; no physical hardware is connected.</p></panel>`}
function cleaning(){return `<div class="page-head"><div><p class="eyebrow">CLEAN / SANITATION</p><h2>Cleaning cycle</h2></div><span class="sim">DEMO WORKFLOW</span></div><panel class="clean"><div class="steps">${['Rinse Lines','Cleaning Solution','Circulate','Water Rinse','Air Purge'].map((x,i)=>`<div class="step ${i<2?'done':''} ${i===2?'current':''}"><b>${i<2?'✓':i+1}</b><span>${x}</span><small>${i<2?'COMPLETE':i===2?'CURRENT':'QUEUED'}</small></div>`).join('')}</div><div class="clean-main"><div class="clean-icon">💧</div><p>STEP 3 OF 5</p><h3>Circulating Cleaning Solution</h3><div class="bar"><i style="width:68%"></i></div><strong>3:42 / 5:00</strong><button class="yellow" data-action="skip">SKIP STEP</button></div></panel>`}
function batches(){return `<div class="page-head"><div><p class="eyebrow">REPORT / HISTORY</p><h2>Batch history</h2></div></div><panel class="wide"><table><thead><tr><th>BATCH</th><th>FLAVOR</th><th>OUTPUT</th><th>DATE</th><th>STATUS</th></tr></thead><tbody>${s.batches.map(b=>`<tr><td><b>${esc(b.id)}</b></td><td><span class="flavor-dot" style="--flavor-color:${flavorColor(b.flavor)}"></span>${esc(b.flavor)}</td><td>${b.qty} bottles</td><td>${esc(b.date)}</td><td><span class="status completed">${esc(b.status)}</span></td></tr>`).join('')||'<tr><td colspan="5">No completed batches yet.</td></tr>'}</tbody></table></panel>`}
function ingredients(){return `<div class="page-head"><div><p class="eyebrow">ANALYTICS / COST MODEL</p><h2>Ingredients & cost</h2></div><span class="sim">QUEUE-BASED FORECAST</span></div><p class="muted" style="text-align:left;margin:-12px 0 18px">Edit unit prices below; the planned ingredient cost recalculates from queued recipes, bottle sizes, and run quantities.</p>`}
function reports(){let completed=s.batches.reduce((a,b)=>a+Number(b.qty||0),0),current=s.running?Number(s.bottles||0):0,total=completed+current,gallons=total*(Number(s.ouncesPerBottle)||16)/128,byFlavor=Object.fromEntries(catalog.map(([f])=>[f,s.batches.filter(b=>b.flavor===f).reduce((a,b)=>a+Number(b.qty||0),0)+(s.running&&s.activeRun?.flavor===f?current:0)])),peak=Math.max(1,...Object.values(byFlavor));return `<div class="page-head"><div><p class="eyebrow">REPORT / PERFORMANCE</p><h2>Production reports</h2></div><div class="tabs"><button class="active">DAILY</button><button>WEEKLY</button><button>MONTHLY</button></div></div><div class="metrics">${[['TOTAL BOTTLES',total,'completed + live run'],['TOTAL GALLONS',gallons.toFixed(1),'based on bottle size'],['YIELD','98.4%','demo estimate'],['COMPLETED BATCHES',s.batches.length,'from batch history']].map(x=>`<panel><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></panel>`).join('')}</div><panel class="wide equipment-report"><div class="panel-head"><h3>Equipment performance</h3><span class="sim">REFERENCE LINE / SIMULATION</span></div><div class="equipment-report-grid"><img src="/assets/equipment-reference.jpg" alt="Production equipment reference"><div><p><b>ZUMEX ESSENTIAL PRO</b><br><span class="good">ONLINE</span> · extraction cycle simulated</p><p><b>ZONESUN ZS-YTDP4 · 4 HEAD</b><br><span class="good">ONLINE</span> · ${s.flowRate||2.1} L/min line flow · ${s.bottles}/${s.target} bottles</p><p><b>VEVOR SY-60-V1</b><br><span class="good">ONLINE</span> · ${Math.max(0,s.bottles-3)} labels applied · ${Math.max(0,s.target-s.bottles)} remaining</p><p><b>CAP / QC</b><br><span class="good">ONLINE</span> · ${s.bottles} bottles checked · 0 demo rejects</p></div></div></panel><panel class="wide chart"><div class="panel-head"><h3>Production by flavor</h3><span class="muted">Completed batch history ${s.running?' + live run':''}</span></div><div class="bars">${catalog.filter(([f])=>byFlavor[f]>0).map(([f,,color])=>`<div style="--flavor-color:${color}"><i style="height:${Math.max(5,byFlavor[f]/peak*100)}%"></i><span>${esc(f)}</span><b>${byFlavor[f]}</b></div>`).join('')||'<p>No production recorded yet.</p>'}</div></panel>`}
function ai(){return `<aside class="ai"><div class="ai-head"><div><span class="ai-orb">✦</span><b>MONSTA AI</b><small>DEMO OPERATOR</small></div><button class="close" data-action="ai" aria-label="Close Monsta AI">×</button></div><div class="ai-messages"><div class="ai-bubble">Ready when you are. What would you like to know?</div></div><div class="suggestions">${["What's running?","How many bottles did we make?","Show low ingredients."].map(x=>`<button data-ai="${x}">${x}</button>`).join('')}</div><div class="ai-composer"><input data-ai-input placeholder="Ask about the production floor…"><button data-action="ai-send" aria-label="Send message">↑</button><label title="Attach file">＋<input type="file" data-ai-file></label><label title="Attach folder">▧<input type="file" webkitdirectory directory multiple data-ai-folder></label><small>${esc(s.aiFile||'')}</small></div></aside>`}
function monitor(){return `<panel class="monitor-panel"><div class="panel-head"><h3>Production room feed</h3><span class="live-badge">● SIMULATED FEED</span></div><div class="feed"><img src="/assets/production-room-feed.png" alt="Simulated Monsta Squeeze production room with staff at the juicer, filling machine, and labeler"><div class="feed-overlay"><b>CAM 01 · FLOOR OVERVIEW</b><span>${new Date().toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase()} · SIMULATED</span></div><div class="staff-card"><b>Jordan M.</b><span>OPERATOR · FILL STATION</span><em>WORKING · ZONESUN ZS-YTDP4</em></div></div><div class="stage-strip"><span>● EXTRACT <b>Alex R.</b></span><span>● RELAY <b>Sam T.</b></span><span>● FILL <b>Jordan M.</b></span><span>○ LABEL <b>QUEUED</b></span></div><button class="yellow" data-action="visual">OPEN LINE VISUALIZATION</button></panel>`}
function visual(){return `<div class="modal-backdrop"><section class="visual-modal"><button class="close" data-action="visual">×</button><p class="eyebrow">SYSTEM VISUALIZATION / DEMO</p><h2>Live material flow</h2><p class="muted">Animated representation of the simulated production path.</p><div class="flow-map"><svg viewBox="0 0 900 180" role="img" aria-label="Animated flow from extraction through relay, filler, cap, label, and finished inventory"><path class="flow-line" d="M90 90 H810"/><circle class="flow-dot" r="8" cy="90"><animate attributeName="cx" values="90;810" dur="4s" repeatCount="indefinite"/></circle></svg>${[['JUICER','ZUMEX Essential Pro'],['CONTAINERS','3 GAL TANKS'],['RELAY','CUSTOM RECIPE RELAY'],['FILL','ZONESUN ZS-YTDP4'],['CAP','CAP / QC'],['LABEL','VEVOR SY-60-V1'],['INVENTORY','FINISHED STOCK']].map((x,i)=>`<div class="flow-node n${i}"><b>${x[0]}</b><span>${x[1]}</span><i>${i<4?'ACTIVE':'READY'}</i></div>`).join('')}</div><div class="visual-footer"><span>RUN: MANGO · ${s.bottles}/${s.target} BOTTLES</span><span class="good">● FLOW NORMAL</span></div></section></div>`}
function aiComposer(){return `<div class="ai-composer"><input data-ai-input placeholder="Ask Monsta AI or issue a demo command…"><button data-action="ai-send">SEND</button><label>＋ FILE<input type="file" data-ai-file></label><label>＋ FOLDER<input type="file" webkitdirectory directory multiple data-ai-folder></label><small>${s.aiFile||'No file attached'}</small></div>`}
function costEditorLegacy(){let rows=s.costs||{Water:.18,'Green Tea':.74,Mango:1.15,Strawberry:1.35,'Classic Lemonade':.95,'Half & Half':.98,'Blueberry Lemonade':1.2,'Raspberry Lemonade':1.2,'Pineapple Lemonade':1.05,Lemon:.92,Sweetener:.48};s.costs=rows;let need={};for(const q of s.queue){let recipe=recipeFor(q.flavor),gallons=q.qty*(Number(s.ouncesPerBottle)||16)/128,items=['Water','Green Tea',q.flavor,'Lemon','Sweetener'];items.forEach((name,i)=>need[name]=(need[name]||0)+gallons*(Number.parseFloat(recipe[i])||0)/100)}let total=Object.entries(need).reduce((a,[k,v])=>a+v*Number(rows[k]||0),0),queued=s.queue.reduce((a,q)=>a+q.qty,0);return `<panel class="wide cost-editor"><div class="panel-head"><h3>Editable ingredient pricing</h3><span class="sim">LOCAL DEMO DATA</span></div><div class="cost-inputs">${Object.entries(rows).map(([k,v])=>`<label>${k}<span>$ / GAL</span><input type="number" min="0" step=".01" value="${v}" data-cost="${k}"></label>`).join('')}</div><div class="cost-summary"><b>PLANNED COST: <span data-cost-total>$${total.toFixed(2)}</span></b><span>${queued} queued bottles · cost per bottle $${(total/Math.max(1,queued)).toFixed(2)} · price input total $${Object.values(rows).reduce((a,v)=>a+Number(v),0).toFixed(2)}</span></div></panel>`}
function costEditor(){let rows=s.costs||{};for(const key of ['Water','Lemon','Sweetener',...catalog.map(([f])=>f)])rows[key]??=key==='Water'?.18:key==='Lemon'?.92:key==='Sweetener'?.48:1.15;for(const key of Object.keys(rows))if(!['Water','Lemon','Sweetener',...catalog.map(([f])=>f)].includes(key))delete rows[key];s.costs=rows;let need={};for(const q of s.queue){if(q.status==='COMPLETED')continue;let recipe=recipeFor(q.flavor),gal=q.qty*(Number(s.ouncesPerBottle)||16)/128;channelNames(q.flavor).forEach((name,i)=>need[name]=(need[name]||0)+gal*(parseFloat(recipe[i])||0)/100)}let total=Object.entries(need).reduce((a,[k,v])=>a+v*Number(rows[k]||0),0),queued=s.queue.filter(q=>q.status!=='COMPLETED').reduce((a,q)=>a+Number(q.qty||0),0);return `<panel class="wide cost-editor"><div class="panel-head"><h3>Editable ingredient pricing</h3><span class="sim">LOCAL DEMO DATA</span></div><div class="cost-inputs">${Object.entries(rows).map(([k,v])=>`<label>${esc(k)}<span>$ / GAL</span><input type="number" min="0" step=".01" value="${v}" data-cost="${esc(k)}"></label>`).join('')}</div><div class="cost-summary"><b>PLANNED COST: <span data-cost-total>$${total.toFixed(2)}</span></b><span>${queued} queued bottles · cost per bottle $${(total/Math.max(1,queued)).toFixed(2)}</span></div></panel>`}
function demoPanel(){return `<panel class="demo-panel"><div><p class="eyebrow">PRESENTATION CONTROLS</p><h3>Demo mode</h3></div><span class="muted">SIMULATION SPEED</span><button data-action="speed" data-speed="1">1X</button><button data-action="speed" data-speed="5">5X</button><button data-action="speed" data-speed="10">10X</button><button data-action="low">TRIGGER LOW INGREDIENT</button><button data-action="flow-error">TRIGGER FLOW ERROR</button><button data-action="refill">REFILL ALL TANKS</button><button data-action="complete">COMPLETE CURRENT BATCH</button><button data-action="reset">RESET DEMO</button></panel>`}
function equipment(){return `<panel class="equipment-strip"><div class="panel-head"><h3>Line equipment</h3><span class="sim">REFERENCE / SIMULATED</span></div><div class="equipment-grid"><img src="/assets/equipment-reference.jpg" alt="Monsta Squeeze production equipment reference showing juicer, four-head filler, and bottle labeler"><div><b>JUICE / EXTRACT → FILL → CAP / QC → LABEL</b><p class="muted">Actual small-scale line reference: citrus extraction, four-head fill, and bottle labeling.</p><button class="yellow" data-page="reports">VIEW EQUIPMENT REPORT</button></div></div></panel>`}
function settings(){return `<div class="page-head"><div><p class="eyebrow">SYSTEM / SETTINGS</p><h2>OPOS settings</h2></div><span class="sim">V0 DEMO CONFIGURATION</span></div><div class="metrics"><panel><span>MODE</span><b>DEMO</b><small>Hardware disconnected</small></panel><panel><span>SIMULATION SPEED</span><b>${s.speed}X</b><small>Use demo controls below</small></panel><panel><span>DATA STORE</span><b>LOCAL</b><small>Browser localStorage</small></panel><panel><span>LINE STATUS</span><b class="good">ONLINE</b><small>Simulated equipment</small></panel></div>${demoPanel()}<panel class="wide"><div class="panel-head"><h3>Navigation & access</h3><span class="muted">Mobile and desktop menus share this state</span></div><p class="muted">OPOS V0 is intentionally unauthenticated and hardware-free. Settings here document the demo boundary before production integrations are added.</p></panel>`}
function page(){return ({dashboard,queue,prep,recipes,recipeEditor,inventory,ingredients,production,relay,cleaning,batches,reports,settings}[s.page]||dashboard)()}
function render(){const app=document.querySelector('#app'),focused=document.activeElement;let selector=null;if(focused?.matches('input,textarea,select')){if(focused.matches('[data-run-qty]'))selector='[data-run-qty]';else if(focused.matches('[data-ai-input]'))selector='[data-ai-input]';else if(focused.matches('[data-ratio]'))selector=`[data-ratio="${focused.dataset.ratio}"]`;else if(focused.matches('[data-cost]'))selector=`[data-cost="${CSS.escape(focused.dataset.cost)}"]`;else if(focused.matches('[data-relay-flavor]'))selector='[data-relay-flavor]'}const value=selector?focused.value:null,start=selector&&typeof focused.selectionStart==='number'?focused.selectionStart:null;app.innerHTML=header()+`<main>${page()}${s.page==='ingredients'?costEditor():''}${s.page==='dashboard'?equipment()+monitor():''}</main>${mobileNav()}<button class="ai-fab" data-action="ai">✦<span>MONSTA AI</span></button>${s.ai?ai():''}${s.visual?visual():''}${s.toast?`<div class="toast">✓ ${esc(s.toast)}</div>`:''}`;bind();if(selector){let next=app.querySelector(selector);if(next){next.focus();if(value!==null)next.value=value;if(start!==null)next.setSelectionRange?.(start,start)}}}
function recipeTotal(){return [...document.querySelectorAll('[data-ratio]')].reduce((a,x)=>a+(Number(x.value)||0),0)}function refreshRecipeValidity(){let total=recipeTotal(),valid=Math.abs(total-100)<.001,display=document.querySelector('[data-recipe-total]');if(display)display.textContent=`${total.toFixed(0)}%`;display?.parentElement?.classList.toggle('ready',valid);display?.parentElement?.classList.toggle('blocked',!valid);document.querySelectorAll('[data-action="save-recipe"],[data-action="load"]').forEach(b=>b.disabled=!valid);document.querySelector('.page-head .readiness')?.replaceChildren(document.createTextNode(`● ${valid?'RECIPE READY':'RECIPE INVALID'}`));document.querySelector('.page-head .readiness')?.classList.toggle('ready',valid);document.querySelector('.page-head .readiness')?.classList.toggle('blocked',!valid)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{s.page=b.dataset.page;s.menu=false;save();render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionLatest(b.dataset.action,b.dataset.id||b.dataset.speed,b.dataset.flavor,b.dataset.index));document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>answer(b.dataset.ai));document.querySelector('[data-recipe-search]')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('[data-recipe-card]').forEach(c=>c.hidden=!c.dataset.recipeCard.includes(q))});document.querySelectorAll('[data-action="choose-flavor"]').forEach(b=>b.addEventListener('click',()=>{s.builderFlavor=b.dataset.flavor;save();document.querySelectorAll('[data-action="choose-flavor"]').forEach(x=>x.classList.toggle('selected',x===b))}));document.querySelector('[data-run-qty]')?.addEventListener('input',e=>{s.builderQty=e.target.value;save()});document.querySelectorAll('[data-ratio]').forEach(input=>input.addEventListener('input',()=>{s.draftRecipe=[...document.querySelectorAll('[data-ratio]')].map(x=>Number(x.value)||0);refreshRecipeValidity();save()}));document.querySelector('[data-relay-flavor]')?.addEventListener('change',e=>{s.selectedRecipe=e.target.value;s.draftRecipe=recipeFor(s.selectedRecipe).map(x=>parseFloat(x)||0);save();render()});document.querySelector('[data-ai-input]')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('[data-action="ai-send"]')?.click()}});document.querySelectorAll('[data-cost]').forEach(input=>input.addEventListener('input',e=>{s.costs=s.costs||{};s.costs[e.target.dataset.cost]=Number(e.target.value)||0;save();let need={};for(const run of s.queue){let ratio=recipeFor(run.flavor),gallons=run.qty*(Number(s.ouncesPerBottle)||16)/128;channelNames(run.flavor).forEach((name,i)=>need[name]=(need[name]||0)+gallons*(Number.parseFloat(ratio[i])||0)/100)}let total=Object.entries(need).reduce((sum,[name,gallons])=>sum+gallons*Number(s.costs[name]||0),0),out=document.querySelector('[data-cost-total]');if(out)out.textContent=`$${total.toFixed(2)}`}))}
function answerLegacy(q){let t=q.toLowerCase(),ans;if(t.includes('running'))ans=s.running?`${s.activeRun.flavor} is ${s.paused?'paused':'running'} at ${s.bottles} of ${s.target} bottles.`:'No run is active.';else if(t.includes('bottles')||t.includes('made'))ans=`Today's completed production is ${s.batches.reduce((a,x)=>a+x.qty,168)} bottles. The current run is at ${s.bottles}/${s.target}.`;else if(t.includes('low')||t.includes('ingredient'))ans=`Low reservoirs: ${Object.entries(s.inventory).filter(([,v])=>v<55).map(([k])=>k).join(', ')||'none'}.`;else if(t.includes('refill')){s.inventory=Object.fromEntries(Object.entries(s.inventory).map(([k,v])=>[k,Math.min(100,v+25)]));ans='Refilled the simulated ingredient reservoirs by 25 percentage points.';}else if(t.includes('report')){s.page='reports';ans='Opening production reports.';}else if(t.includes('relay')||t.includes('load')){let f=catalog.find(([name])=>t.includes(name.toLowerCase()));if(f)s.selectedRecipe=f[0];s.page='relay';ans=`Recipe Relay opened${f?` with ${f[0]} selected`:''}.`; }else if(t.includes('run')||t.includes('make')||t.includes('add')){let f=catalog.find(([name])=>t.includes(name.toLowerCase()))||catalog[0],m=t.match(/\b(\d{1,3})\b/),qty=Math.min(300,Math.max(1,Number(m?.[1]||48)));createRun(f[0],qty,false);if(/\b(start|run now)\b/.test(t)){actionLatest('start',s.queue.at(-1)?.id);ans=`Started a ${qty}-bottle ${f[0]} demo run.`}else ans=`Added ${qty} ${f[0]} bottles to the production queue. Start it from Queue or Recipe Relay when ready.`;}else ans='I can check the current run, bottle count, low ingredients, open Recipe Relay or Reports, refill mock reservoirs, or add a catalog flavor run.';if(document.querySelector('.ai-messages'))document.querySelector('.ai-messages').insertAdjacentHTML('beforeend',`<div class="ai-user">${esc(q)}</div><div class="ai-bubble">${esc(ans)}</div>`);if(t.includes('report')||t.includes('relay')||/\b(start|run now)\b/.test(t))render();else{save()}}
