function openRun(q){if(!q)return false;s.activeRun={...q,status:'RUNNING',startedAt:Date.now()};s.batchId=runId(q.flavor);s.target=Number(q.qty);s.bottles=0;s.selectedRecipe=q.flavor;s.draftRecipe=null;s.draftFlavor=null;s.queue=s.queue.map(x=>String(x.id)===String(q.id)?{...x,status:'RUNNING'}:x);s.running=true;s.paused=false;s.page='production';startTimer();save();render();return true}
